var logger13 = createLogger("repository-service");
var RepositoryService = class {
  /**
   * Creates a new RepositoryService instance
   *
   * @param authClient - Authentication client for API requests
   * @param serverConfigService - Service for accessing server configuration
   */
  constructor(authClient2, serverConfigService2) {
    this.authClient = authClient2;
    this.serverConfigService = serverConfigService2;
  }
  /**
   * Discovers Git repositories in the configured base path
   *
   * Scans the directory tree starting from the server-configured repository base path
   * to find all Git repositories. The scan is recursive and identifies directories
   * containing a `.git` subdirectory.
   *
   * The discovery process:
   * 1. Retrieves the base path from server configuration
   * 2. Makes an authenticated API request to scan for repositories
   * 3. Returns repository metadata including name, path, and last modified time
   *
   * @returns Promise resolving to an array of discovered repositories
   *          Returns empty array if discovery fails or no repositories found
   *
   * @throws Never throws - errors are logged and empty array returned
   *
   * @example
   * ```typescript
   * const repoService = new RepositoryService(authClient, serverConfig);
   *
   * // Discover all repositories
   * const repos = await repoService.discoverRepositories();
   *
   * // Use in autocomplete
   * repos.forEach(repo => {
   *   console.log(`Found: ${repo.name} at ${repo.path}`);
   *   console.log(`Last modified: ${new Date(repo.lastModified)}`);
   * });
   *
   * // Handle empty results
   * if (repos.length === 0) {
   *   console.log('No repositories found or discovery failed');
   * }
   * ```
   *
   * @see web/src/server/routes/repositories.ts:15 - Server endpoint implementation
   * @see web/src/server/services/file-system.service.ts - Underlying directory scanning
   */
  async discoverRepositories() {
    try {
      const basePath = await this.serverConfigService.getRepositoryBasePath();
      const response = await fetch(
        `/api/repositories/discover?path=${encodeURIComponent(basePath)}`,
        {
          headers: this.authClient.getAuthHeader()
        }
      );
      if (response.ok) {
        const repositories = await response.json();
        logger13.debug(`Discovered ${repositories.length} repositories`);
        return repositories;
      } else {
        logger13.error("Failed to discover repositories");
        return [];
      }
    } catch (error) {
      logger13.error("Error discovering repositories:", error);
      return [];
    }
  }
};

// src/client/services/session-service.ts
init_types();
init_logger();
var logger14 = createLogger("session-service");
var SessionService = class {
  constructor(authClient2) {
    this.authClient = authClient2;
  }
  /**
   * Create a new terminal session
   *
   * Creates a terminal session with the specified configuration. The session
   * will start executing the provided command in the given working directory.
   *
   * **Session Lifecycle:**
   * 1. Session is created with 'starting' status
   * 2. PTY (pseudo-terminal) is spawned with the command
   * 3. Session transitions to 'running' status
   * 4. Session remains active until the process exits
   * 5. Session transitions to 'exited' status with exit code
   *
   * **Git Integration:**
   * When gitRepoPath and gitBranch are provided, the session gains:
   * - Branch name display in the UI
   * - Ahead/behind commit tracking
   * - Uncommitted changes indicators
   * - Worktree awareness
   *
   * **Title Modes:**
   * - `none`: No title management, apps control the title
   * - `filter`: Block all title changes from applications
   * - `static`: Fixed title format: "path — command — session"
   * - `dynamic`: Static format + live activity indicators
   *
   * @param sessionData - The session configuration
   * @returns Promise resolving to the created session details
   *
   * @example
   * ```typescript
   * // Basic shell session
   * const { sessionId } = await sessionService.createSession({
   *   command: ['bash'],
   *   workingDir: process.env.HOME
   * });
   *
   * // Development server with Git tracking
   * const devSession = await sessionService.createSession({
   *   command: ['npm', 'run', 'dev'],
   *   workingDir: '/path/to/project',
   *   name: 'Dev Server',
   *   gitRepoPath: '/path/to/project',
   *   gitBranch: 'main',
   *   titleMode: TitleMode.DYNAMIC,
   *   cols: 120,
   *   rows: 40
   * });
   *
   * // Spawn in new Terminal.app window (Mac only)
   * const terminalSession = await sessionService.createSession({
   *   command: ['vim', 'README.md'],
   *   workingDir: '/path/to/project',
   *   spawn_terminal: true
   * });
   * ```
   *
   * @throws Error with detailed message if:
   * - Invalid command array provided
   * - Working directory doesn't exist or isn't accessible
   * - Authentication fails (401)
   * - Server error occurs (500)
   * - Network request fails
   */
  async createSession(sessionData) {
    try {
      const response = await fetch("/api/sessions", {
        method: "POST" /* POST */,
        headers: {
          "Content-Type": "application/json",
          ...this.authClient.getAuthHeader()
        },
        body: JSON.stringify(sessionData)
      });
      if (response.ok) {
        const result = await response.json();
        logger14.log("Session created successfully:", result.sessionId);
        return result;
      } else {
        const error = await response.json();
        const errorMessage = error.details || error.error || "Unknown error";
        logger14.error("Failed to create session:", errorMessage);
        throw new Error(errorMessage);
      }
    } catch (error) {
      if (error instanceof Error && error.message) {
        throw error;
      }
      logger14.error("Error creating session:", error);
      throw new Error("Failed to create session");
    }
  }
};

// src/client/utils/command-utils.ts
function parseCommand(commandStr) {
  const args = [];
  let current = "";
  let inQuotes = false;
  let quoteChar = "";
  for (let i7 = 0; i7 < commandStr.length; i7++) {
    const char = commandStr[i7];
    if ((char === '"' || char === "'") && !inQuotes) {
      inQuotes = true;
      quoteChar = char;
    } else if (char === quoteChar && inQuotes) {
      inQuotes = false;
      quoteChar = "";
    } else if (char === " " && !inQuotes) {
      if (current) {
        args.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }
  if (current) {
    args.push(current);
  }
  return args;
}

