// src/client/components/autocomplete-manager.ts
init_logger();
var logger16 = createLogger("autocomplete-manager");
var AutocompleteManager = class {
  constructor(authClient2) {
    this.repositories = [];
    this.authClient = authClient2;
  }
  setAuthClient(authClient2) {
    this.authClient = authClient2;
  }
  setRepositories(repositories) {
    this.repositories = repositories;
  }
  async fetchCompletions(path) {
    if (!path) return [];
    try {
      const response = await fetch(`/api/fs/completions?path=${encodeURIComponent(path)}`, {
        headers: this.authClient?.getAuthHeader() || {}
      });
      if (!response.ok) {
        logger16.error("Failed to fetch completions");
        return [];
      }
      const data = await response.json();
      const completions = data.completions || [];
      const directoryCompletions = completions.filter((item) => item.type === "directory");
      const isSearchingByName = !path.includes("/") || (path.match(/\//g) || []).length === 1 && path.endsWith("/") === false;
      if (isSearchingByName && this.repositories.length > 0) {
        const searchTerm = path.toLowerCase().replace("~/", "");
        const matchingRepos = this.repositories.filter((repo) => repo.folderName.toLowerCase().includes(searchTerm)).map((repo) => ({
          name: repo.folderName,
          path: repo.relativePath,
          type: "directory",
          suggestion: repo.path,
          isRepository: true,
          gitBranch: repo.gitBranch,
          gitStatusCount: 0
          // Repository service doesn't provide this yet
        }));
        const existingPaths = new Set(directoryCompletions.map((c6) => c6.suggestion));
        const uniqueRepos = matchingRepos.filter((repo) => !existingPaths.has(repo.suggestion));
        directoryCompletions.push(...uniqueRepos);
      }
      const sortedCompletions = this.sortCompletions(directoryCompletions, path);
      return sortedCompletions.slice(0, 20);
    } catch (error) {
      logger16.error("Error fetching completions:", error);
      return [];
    }
  }
  sortCompletions(completions, originalPath) {
    const searchTerm = originalPath.toLowerCase();
    const lastPathSegment = searchTerm.split("/").pop() || "";
    return completions.sort((a3, b3) => {
      const aNameMatch = a3.name.toLowerCase() === lastPathSegment;
      const bNameMatch = b3.name.toLowerCase() === lastPathSegment;
      if (aNameMatch && !bNameMatch) return -1;
      if (!aNameMatch && bNameMatch) return 1;
      const aStartsWith = a3.name.toLowerCase().startsWith(lastPathSegment);
      const bStartsWith = b3.name.toLowerCase().startsWith(lastPathSegment);
      if (aStartsWith && !bStartsWith) return -1;
      if (!aStartsWith && bStartsWith) return 1;
      if (a3.isRepository && !b3.isRepository) return -1;
      if (!a3.isRepository && b3.isRepository) return 1;
      return a3.name.localeCompare(b3.name);
    });
  }
  filterCompletions(completions, searchTerm) {
    if (!searchTerm) return completions;
    const lowerSearch = searchTerm.toLowerCase();
    return completions.filter((item) => {
      const name = item.name.toLowerCase();
      const path = item.path.toLowerCase();
      return name.includes(lowerSearch) || path.includes(lowerSearch);
    });
  }
};

