// src/shared/utils/git.ts
function getBaseRepoName(repoPath) {
  if (repoPath === "/") {
    return "";
  }
  const parts = repoPath.split("/");
  const lastPart = parts[parts.length - 1] || repoPath;
  const worktreePatterns = [
    /-tree(?:test)?$/i,
    // -treetest, -tree
    /-worktree$/i,
    // -worktree
    /-wt-\w+$/i,
    // -wt-feature
    /-work$/i,
    // -work
    /-temp$/i,
    // -temp
    /-branch-\w+$/i,
    // -branch-feature
    /-\w+$/i
    // Any single-word suffix (catches -notifications, -feature, etc.)
  ];
  for (const pattern of worktreePatterns) {
    if (pattern.test(lastPart)) {
      const baseName = lastPart.replace(pattern, "");
      if (baseName && baseName.length >= 2) {
        return baseName;
      }
    }
  }
  return lastPart;
}

