  selectImage() {
    if (!this.callbacks) return;
    const filePicker = this.callbacks.querySelector("file-picker");
    if (filePicker && typeof filePicker.openImagePicker === "function") {
      filePicker.openImagePicker();
    } else {
      logger34.error("File picker component not found or openImagePicker method not available");
    }
  }
