// src/client/components/session-view/loading-animation-manager.ts
var LoadingAnimationManager = class {
  constructor() {
    this.loading = false;
    this.loadingFrame = 0;
    this.loadingInterval = null;
  }
  /**
   * Check if currently in loading state
   */
  isLoading() {
    return this.loading;
  }
  /**
   * Get current loading frame for animation
   */
  getLoadingFrame() {
    return this.loadingFrame;
  }
  /**
   * Start loading animation with callback for updates
   */
  startLoading(onUpdate) {
    this.loading = true;
    this.loadingFrame = 0;
    this.loadingInterval = window.setInterval(() => {
      this.loadingFrame = (this.loadingFrame + 1) % 4;
      if (onUpdate) {
        onUpdate();
      }
    }, 200);
  }
  /**
   * Stop loading animation
   */
  stopLoading() {
    this.loading = false;
    if (this.loadingInterval) {
      clearInterval(this.loadingInterval);
      this.loadingInterval = null;
    }
  }
  /**
   * Get current loading animation text frame
   */
  getLoadingText() {
    const frames = ["\u280B", "\u2819", "\u2839", "\u2838", "\u283C", "\u2834", "\u2826", "\u2827", "\u2807", "\u280F"];
    return frames[this.loadingFrame % frames.length];
  }
  /**
   * Clean up any active intervals
   */
  cleanup() {
    if (this.loadingInterval) {
      clearInterval(this.loadingInterval);
      this.loadingInterval = null;
    }
  }
};

// src/client/components/session-view/mobile-input-manager.ts
var MobileInputManager = class {
  constructor(sessionView) {
    this.inputManager = null;
    this.sessionView = sessionView;
  }
  setInputManager(inputManager) {
    this.inputManager = inputManager;
  }
  handleMobileInputToggle() {
    if (this.sessionView.shouldUseDirectKeyboard()) {
      this.sessionView.focusHiddenInput();
      return;
    }
    this.sessionView.toggleMobileInputDisplay();
  }
  async handleMobileInputSendOnly(text) {
    const textToSend = text?.trim();
    if (!textToSend) return;
    try {
      if (this.inputManager) {
        await this.inputManager.sendInputText(textToSend);
      }
      this.sessionView.clearMobileInputText();
      this.sessionView.requestUpdate();
      this.sessionView.closeMobileInput();
      if (this.sessionView.shouldRefocusHiddenInput()) {
        this.sessionView.refocusHiddenInput();
      }
      this.sessionView.refreshTerminalAfterMobileInput();
    } catch (error) {
      console.error("error sending mobile input", error);
    }
  }
  async handleMobileInputSend(text) {
    const textToSend = text?.trim();
    if (!textToSend) return;
    try {
      if (this.inputManager) {
        await this.inputManager.sendInputText(textToSend);
        await this.inputManager.sendInput("enter");
      }
      this.sessionView.clearMobileInputText();
      this.sessionView.requestUpdate();
      this.sessionView.closeMobileInput();
      if (this.sessionView.shouldRefocusHiddenInput()) {
        this.sessionView.refocusHiddenInput();
      }
      this.sessionView.refreshTerminalAfterMobileInput();
    } catch (error) {
      console.error("error sending mobile input", error);
    }
  }
  handleMobileInputCancel() {
    this.sessionView.closeMobileInput();
    this.sessionView.clearMobileInputText();
    if (this.sessionView.shouldRefocusHiddenInput()) {
      this.sessionView.startFocusRetention();
      this.sessionView.delayedRefocusHiddenInput();
    }
  }
  cleanup() {
    this.inputManager = null;
  }
};

// src/client/components/session-view/session-actions-handler.ts
init_auth_client();
init_logger();
var logger39 = createLogger("session-actions-handler");
var SessionActionsHandler = class {
  constructor() {
    this.callbacks = null;
  }
  setCallbacks(callbacks) {
    this.callbacks = callbacks;
  }
  async handleRename(sessionId, newName) {
    if (!this.callbacks) return;
    const session = this.callbacks.getSession();
    if (!session || sessionId !== session.id) return;
    const result = await renameSession(sessionId, newName, authClient);
    if (result.success) {
      const actualName = newName;
      this.callbacks.setSession({ ...session, name: actualName });
      const sessionName = actualName || session.command.join(" ");
      titleManager.setSessionTitle(sessionName);
      this.callbacks.dispatchEvent(
        new CustomEvent("session-renamed", {
          detail: { sessionId, newName: actualName },
          bubbles: true,
          composed: true
        })
      );
      logger39.log(`Session ${sessionId} renamed to: ${actualName}`);
    } else {
      this.callbacks.dispatchEvent(
        new CustomEvent("error", {
          detail: `Failed to rename session: ${result.error}`,
          bubbles: true,
          composed: true
        })
      );
    }
  }
  async handleTerminateSession() {
    if (!this.callbacks) return;
    const session = this.callbacks.getSession();
    if (!session) return;
    await sessionActionService.terminateSession(session, {
      authClient,
      callbacks: {
        onError: (message) => {
          if (this.callbacks) {
            this.callbacks.dispatchEvent(
              new CustomEvent("error", {
                detail: message,
                bubbles: true,
                composed: true
              })
            );
          }
        },
        onSuccess: () => {
        }
      }
    });
  }
  async handleClearSession() {
    if (!this.callbacks) return;
    const session = this.callbacks.getSession();
    if (!session) return;
    await sessionActionService.clearSession(session, {
      authClient,
      callbacks: {
        onError: (message) => {
          if (this.callbacks) {
            this.callbacks.dispatchEvent(
              new CustomEvent("error", {
                detail: message,
                bubbles: true,
                composed: true
              })
            );
          }
        },
        onSuccess: () => {
          if (this.callbacks) {
            this.callbacks.handleBack();
          }
        }
      }
    });
  }
  handleToggleViewMode() {
    if (!this.callbacks) return;
    const session = this.callbacks.getSession();
    if (!session?.gitRepoPath) return;
    const currentMode = this.callbacks.getViewMode();
    const newMode = currentMode === "terminal" ? "worktree" : "terminal";
    this.callbacks.setViewMode(newMode);
    if (newMode === "terminal") {
      requestAnimationFrame(() => {
        this.callbacks?.ensureTerminalInitialized();
      });
    }
  }
  handleSessionExit(sessionId, exitCode) {
    if (!this.callbacks) return;
    const session = this.callbacks.getSession();
    if (!session || sessionId !== session.id) return;
    logger39.log("Session exit event received", { sessionId, exitCode });
    this.callbacks.setSession({ ...session, status: "exited" });
    this.callbacks.requestUpdate();
    this.callbacks.dispatchEvent(
      new CustomEvent("session-status-changed", {
        detail: {
          sessionId: session.id,
          newStatus: "exited",
          exitCode
        },
        bubbles: true
      })
    );
    const urlParams = new URLSearchParams(window.location.search);
    const sessionParam = urlParams.get("session");
    if (sessionParam === sessionId) {
      logger39.log(`Session ${sessionId} exited, attempting to close window`);
      setTimeout(() => {
        try {
          window.close();
          setTimeout(() => {
            logger39.log("Window close failed - likely opened as a regular tab");
          }, 100);
        } catch (e8) {
          logger39.warn("Failed to close window:", e8);
        }
      }, 500);
    }
  }
  // Check if worktree view is available
  canToggleViewMode(session) {
    return !!session?.gitRepoPath;
  }
};

