    if (e8.metaKey) parts.push("Cmd");
    if (e8.shiftKey) parts.push("Shift");
    if (e8.altKey) parts.push(navigator.platform.toLowerCase().includes("mac") ? "Option" : "Alt");
    parts.push(e8.key);
    return parts.join("+");
